import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';
import logo from '../assets/Imagen1.png'; // Ajusta la ruta si es necesario

function Navbar() {
  const { user, logout } = useContext(AuthContext);

  return (
    <nav className="navbar navbar-expand-lg navbar-dark bg-dark px-4">
      <Link className="navbar-brand d-flex align-items-center" to="/">
        <img src={logo} alt="Natura Alhambra" height="40" className="me-2" />
        <span className="fw-bold text-success">Natura Alhambra</span>
      </Link>

      <button className="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#mainNavbar">
        <span className="navbar-toggler-icon"></span>
      </button>

      <div className="collapse navbar-collapse" id="mainNavbar">
        <ul className="navbar-nav ms-auto">
          <li className="nav-item">
            <Link className="nav-link" to="/">Inicio</Link>
          </li>
          <li className="nav-item">
            <Link className="nav-link" to="/houses">Casas</Link>
          </li>
          {user && (
            <li className="nav-item">
              <Link className="nav-link" to="/reservations">Mis Reservas</Link>
            </li>
          )}
          <li className="nav-item">
            {user ? (
              <button className="btn btn-outline-light btn-sm ms-2" onClick={logout}>
                Cerrar sesión
              </button>
            ) : (
              <Link className="btn btn-outline-success btn-sm ms-2" to="/login">
                Iniciar sesión
              </Link>
            )}
          </li>
        </ul>
      </div>
    </nav>
  );
}

export default Navbar;
